  "implementation": "def solve(case):
    import json
    # Extract required fields
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    # Validate word_labels length
    if len(word_labels) != len(word_token_indices):
        raise ValueError('word_labels length must equal word_token_indices length')

    # Collect all token indices and check coverage, no overlap, in range
    seen = set()
    for idx_list in word_token_indices:
        for idx in idx_list:
            if not isinstance(idx, int) or idx < 0 or idx >= token_count:
                raise ValueError(f'Token index {idx} out of range [0, {token_count-1}]')
            if idx in seen:
                raise ValueError(f'Duplicate token index {idx}')
            seen.add(idx)

    if len(seen) != token_count:
        raise ValueError(f'Cover token indices incomplete: got {len(seen)}, expected {token_count}')

    # Build token_labels array
    token_labels = [0] * token_count  # default 0, but will overwrite with actual labels
    # However, we need to ensure each token gets the correct label from its word group
    for idx_list, label in zip(word_token_indices, word_labels):
        for idx in idx_list:
            token_labels[idx] = label

    # Compute kept_indices
    kept_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]

    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
}
